/**
 * Netlify Function: send-reset-email
 * Sends a professional password-reset email via Resend.
 * The actual reset token/link is generated by Supabase Auth.
 *
 * POST /api/send-reset-email
 * Body: { email, resetUrl }
 *
 * Security: RESEND_API_KEY is a server-side secret, never sent to client.
 */

import { Resend } from "resend";

const resend = new Resend(process.env.RESEND_API_KEY);

const FROM_EMAIL =
  process.env.RESEND_FROM_EMAIL || "CareOS <no-reply@careoshealth.com>";
const APP_URL = process.env.APP_URL || "https://careoshealth.netlify.app";

/** Escape HTML to prevent XSS in email templates */
function escapeHtml(str) {
  if (!str || typeof str !== "string") return "";
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

/** Build the HTML password reset email template */
function buildResetEmail(email, resetUrl) {
  const safeEmail = escapeHtml(email);
  const safeUrl = encodeURI(resetUrl);

  return `<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta http-equiv="X-UA-Compatible" content="IE=edge" />
  <title>Reset your CareOS password</title>
  <style>
    body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
    table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
    img { -ms-interpolation-mode: bicubic; border: 0; outline: none; text-decoration: none; }
    body { margin: 0; padding: 0; background-color: #f1f5f9; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }

    .email-wrapper { width: 100%; background-color: #f1f5f9; padding: 40px 16px; }
    .email-card { max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 24px rgba(0,0,0,0.06); }

    .email-header { background: linear-gradient(135deg, #0891b2 0%, #0e7490 100%); padding: 36px 40px 32px; text-align: center; }
    .email-logo-icon { display: inline-block; width: 40px; height: 40px; background: rgba(255,255,255,0.2); border-radius: 10px; text-align: center; line-height: 40px; font-size: 20px; vertical-align: middle; margin-right: 10px; }
    .email-logo-text { font-size: 22px; font-weight: 700; color: #ffffff; letter-spacing: -0.3px; vertical-align: middle; }
    .email-tagline { font-size: 13px; color: rgba(255,255,255,0.75); margin-top: 6px; }

    .email-body { padding: 40px; }
    .email-icon-circle { width: 72px; height: 72px; background: #f0fdff; border: 2px solid #a5f3fc; border-radius: 50%; text-align: center; line-height: 72px; font-size: 32px; margin: 0 auto 24px; }
    .email-greeting { font-size: 22px; font-weight: 700; color: #0f172a; margin: 0 0 16px; text-align: center; }
    .email-text { font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 24px; }
    .email-text strong { color: #1e293b; font-weight: 600; }

    .email-divider { border: none; border-top: 1px solid #e2e8f0; margin: 28px 0; }

    .email-cta-section { text-align: center; margin: 32px 0; }
    .email-cta-btn { display: inline-block; background: #0891b2; color: #ffffff !important; font-size: 15px; font-weight: 600; padding: 14px 36px; border-radius: 10px; text-decoration: none; letter-spacing: 0.01em; }
    .email-cta-btn:hover { background: #0e7490; }

    .email-fallback { margin-top: 20px; font-size: 13px; color: #94a3b8; }
    .email-fallback a { color: #0891b2; word-break: break-all; }

    .email-warning { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 8px; padding: 14px 16px; font-size: 13px; color: #9a3412; line-height: 1.6; margin-top: 24px; }

    .email-security-notice { background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 8px; padding: 14px 16px; font-size: 13px; color: #14532d; line-height: 1.6; margin-top: 16px; }

    .email-footer { background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 28px 40px; text-align: center; }
    .email-footer p { font-size: 12px; color: #94a3b8; margin: 0 0 6px; line-height: 1.6; }
    .email-footer a { color: #64748b; text-decoration: underline; }

    @media (max-width: 600px) {
      .email-body { padding: 28px 24px; }
      .email-footer { padding: 20px 24px; }
      .email-header { padding: 28px 24px; }
      .email-greeting { font-size: 20px; }
      .email-cta-btn { padding: 14px 24px; }
    }
  </style>
</head>
<body>
  <div class="email-wrapper">
    <table class="email-card" cellpadding="0" cellspacing="0" role="presentation" width="100%">

      <!-- Header -->
      <tr>
        <td class="email-header">
          <span class="email-logo-icon">🏥</span>
          <span class="email-logo-text">CareOS</span>
          <div class="email-tagline">Your Personal Health Record Platform</div>
        </td>
      </tr>

      <!-- Body -->
      <tr>
        <td class="email-body">
          <div class="email-icon-circle">🔑</div>

          <h1 class="email-greeting">Password Reset Request</h1>

          <p class="email-text">
            We received a request to reset the password for the CareOS account associated with
            <strong>${safeEmail}</strong>.
            If this was you, click the button below to set a new password.
          </p>

          <div class="email-cta-section">
            <a href="${safeUrl}" class="email-cta-btn" target="_blank" rel="noopener noreferrer">
              Reset Password
            </a>
            <div class="email-fallback">
              Button not working? Copy and paste this link:<br />
              <a href="${safeUrl}" target="_blank" rel="noopener noreferrer">
                ${safeUrl}
              </a>
            </div>
          </div>

          <div class="email-warning">
            ⏱️ <strong>This link expires in 1 hour.</strong> If it has expired, return to CareOS and request a new password reset link.
          </div>

          <div class="email-security-notice">
            🔒 <strong>If you didn't request this,</strong> you can safely ignore this email.
            Your password won't be changed unless you click the link above and actively set a new password.
            If you're concerned about account security, sign in and change your password immediately.
          </div>

          <hr class="email-divider" />

          <p class="email-text" style="font-size: 13px; color: #94a3b8; margin-bottom: 0;">
            For your security, this reset link is single-use and can only be opened once.
            After setting your new password, you'll be signed in automatically.
          </p>
        </td>
      </tr>

      <!-- Footer -->
      <tr>
        <td class="email-footer">
          <p>
            You received this email because a password reset was requested for your
            <a href="${APP_URL}" target="_blank" rel="noopener noreferrer">CareOS</a> account.
          </p>
          <p style="margin-top: 10px;">
            <a href="${APP_URL}" target="_blank" rel="noopener noreferrer">Visit CareOS</a>
            &nbsp;·&nbsp;
            <a href="${APP_URL}/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
          </p>
          <p style="margin-top: 12px; color: #cbd5e1;">
            © ${new Date().getFullYear()} CareOS. All rights reserved.
          </p>
        </td>
      </tr>

    </table>
  </div>
</body>
</html>`;
}

export default async function handler(req, context) {
  // Only allow POST
  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json" },
    });
  }

  // Verify Resend is configured
  if (!process.env.RESEND_API_KEY) {
    console.error("RESEND_API_KEY is not configured");
    return new Response(
      JSON.stringify({ error: "Email service not configured" }),
      { status: 503, headers: { "Content-Type": "application/json" } }
    );
  }

  let body;
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  const { email, resetUrl } = body;

  // Validate inputs
  if (!email || !resetUrl) {
    return new Response(
      JSON.stringify({ error: "email and resetUrl are required" }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  // Basic email format validation
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return new Response(JSON.stringify({ error: "Invalid email address" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  // Validate reset URL originates from our app or Supabase
  const expectedOrigin = APP_URL.replace(/\/$/, "");
  if (
    !resetUrl.startsWith(expectedOrigin) &&
    !resetUrl.startsWith("https://znhrhosoqccyerapcwpv.supabase.co")
  ) {
    console.warn(
      `Blocked suspicious resetUrl: ${resetUrl.substring(0, 80)}`
    );
    return new Response(JSON.stringify({ error: "Invalid reset URL" }), {
      status: 400,
      headers: { "Content-Type": "application/json" },
    });
  }

  try {
    const { data, error } = await resend.emails.send({
      from: FROM_EMAIL,
      to: [email],
      subject: "Reset your CareOS password",
      html: buildResetEmail(email, resetUrl),
      // Idempotency key — unique per email + hour to prevent duplicate sends
      headers: {
        "X-Entity-Ref-ID": `reset-${email}-${new Date().toISOString().substring(0, 13)}`,
      },
    });

    if (error) {
      console.error("Resend API error (reset email):", error);
      return new Response(JSON.stringify({ error: "Failed to send email" }), {
        status: 502,
        headers: { "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ success: true, id: data?.id }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  } catch (err) {
    console.error("Unexpected error sending reset email:", err);
    return new Response(JSON.stringify({ error: "Internal server error" }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
}
